// NetworkImage.tsx
// Built-in component for async image loading from network URLs
// Generated by ReactJsonUI

/* eslint-disable @next/next/no-img-element -- framework-agnostic by design:
   NetworkImage must work outside Next.js, so it renders a plain <img>
   (no next/image dependency). */
/* eslint-disable react-hooks/set-state-in-effect -- the synchronous setState
   pair at the top of the effect RESETS loading/error when `src` changes
   before the preload starts; it is intentional reset semantics, not
   derived state. */

"use client";

import React, { useState, useEffect, useRef } from 'react';

interface NetworkImageProps {
  id?: string;
  src?: string;
  alt?: string;
  className?: string;
  // 'fit' is the canonical JsonUI alias for 'contain' — the converter
  // normalizes it, but accept it here too so the contract can't drift.
  contentMode?: 'cover' | 'contain' | 'fill' | 'none' | 'scaleDown' | 'fit';
  placeholder?: string;
  // No-src display — the canonical networkImage.noSrc chain
  // (shared/core/attribute_semantics.json): with no src the view shows
  // defaultImage; placeholder belongs to the loading state; on error it
  // shows errorImage, falling back to defaultImage.
  defaultImage?: string;
  errorImage?: string;
  // Native browser fetch hint, forwarded to the rendered <img>. Renamed on
  // destructure because `loading` is this component's own state name.
  loading?: 'lazy' | 'eager';
  onLoad?: () => void;
  onError?: () => void;
  // The load listener (ticket jui-networkimage-load-listener). transitionDuration
  // is T, the ms of the opacity fade into the loaded or the error image
  // (ease-out); an image the browser already holds is shown at once, with no
  // fade. onLoadStateChange is called on a change only: 'loading' when src is
  // set, then 'loaded' / 'failed' from the load / error events; an image the
  // browser already holds calls 'loaded' alone. loadingRenderer is not a web
  // attribute: the web face draws placeholder.
  transitionDuration?: number;
  onLoadStateChange?: (state: string) => void;
  // Common attribute surface the converter can emit onto any component
  // (onClick binding, bound inline styles, testId/tag data attributes).
  // Every render branch forwards these on its root element so a declaration
  // that passes `jui build` can never fail tsc here
  // (rjui-network-image-onclick-not-forwarded). It is handed the click: a
  // tap inside another tap stops it there (BaseConverter#can_tap_gated_click,
  // jsonui-cli 1.9.1); `() => void` is assignable to it as before.
  onClick?: (e: React.MouseEvent<HTMLElement>) => void;
  // A tap the tap rule makes a button (BaseConverter#keyboard_tap_attrs):
  // its role, its tab stop and the keys that click it.
  role?: string;
  tabIndex?: number;
  onKeyDown?: (e: React.KeyboardEvent<HTMLElement>) => void;
  style?: React.CSSProperties;
  'data-testid'?: string;
  'data-tag'?: string;
}

export const NetworkImage: React.FC<NetworkImageProps> = ({
  id,
  src,
  alt = '',
  className = '',
  // Default is fit/contain — canonical image.defaultContentMode
  // (shared/core/attribute_semantics.json); ios/android default the same way.
  contentMode = 'contain',
  placeholder,
  defaultImage,
  errorImage,
  loading: fetchHint,
  onLoad,
  onError,
  transitionDuration = 0,
  onLoadStateChange,
  onClick,
  role,
  tabIndex,
  onKeyDown,
  style,
  'data-testid': dataTestid,
  'data-tag': dataTag,
}) => {
  // Forwarded onto the root element of every render branch (image, loading
  // box, fallback box) so click targets and test hooks survive state changes.
  const rootProps = {
    id,
    onClick,
    role,
    tabIndex,
    onKeyDown,
    style,
    'data-testid': dataTestid,
    'data-tag': dataTag,
  };
  const [imageUrl, setImageUrl] = useState<string | null>(defaultImage || placeholder || null);
  // Seeded from `src`, not `true`. Nothing is loading when there is no URL to
  // load, and the effect that would correct it runs only AFTER the first
  // paint — so a no-src view painted the loading state once before settling:
  // with a placeholder it showed the placeholder over defaultImage (the exact
  // inversion of the canonical noSrc chain), and without one it flashed the
  // pulsing grey box. Both were recorded by a MutationObserver probe on the
  // shipped build, invisible to a settled screenshot (plan 51-A, #19).
  // No src is undefined, "" or only whitespace (networkImage.noSrc, the
  // same rule SwiftJsonUI and KotlinJsonUI apply): a blank URL is data that is
  // missing, not an image that failed, so it draws defaultImage, not errorImage.
  const noSrc = !src || src.trim() === '';
  const [loading, setLoading] = useState(!noSrc);
  const [error, setError] = useState(false);
  // The fade: 'start' draws the image at opacity 0, 'run' moves it to 1 over
  // transitionDuration ms on the next frame.
  const [fade, setFade] = useState<'none' | 'start' | 'run'>('none');
  // The handler is read through a ref: a handler written inline is a new
  // function every render, and in the effect's dependencies it would load
  // the image again on every render. The ref is written after each render
  // (React reads no ref a render writes), by an effect declared before the
  // load's own, so the load reports to this render's handler.
  const stateHandler = useRef(onLoadStateChange);
  useEffect(() => {
    stateHandler.current = onLoadStateChange;
  });
  const lastState = useRef<string | null>(null);
  const report = (state: string) => {
    if (lastState.current === state) return;
    lastState.current = state;
    stateHandler.current?.(state);
  };

  useEffect(() => {
    if (noSrc || !src) {
      // No source: the canonical no-src display is defaultImage (then
      // placeholder as grace) so a row whose URL becomes empty doesn't
      // keep showing the previous image. Nothing is reported (there is no
      // state name for it), and a src that comes back is reported afresh.
      setImageUrl(defaultImage || placeholder || null);
      setLoading(false);
      setError(false);
      setFade('none');
      lastState.current = null;
      return;
    }

    setLoading(true);
    setError(false);
    setFade('none');

    const img = new Image();
    let cached = false;
    img.onload = () => {
      setImageUrl(src);
      setLoading(false);
      if (!cached && transitionDuration > 0) setFade('start');
      report('loaded');
      onLoad?.();
    };
    img.onerror = () => {
      setError(true);
      setLoading(false);
      const errorDisplay = errorImage || defaultImage;
      if (errorDisplay) {
        setImageUrl(errorDisplay);
        if (transitionDuration > 0) setFade('start');
      }
      report('failed');
      onError?.();
    };
    img.src = src;
    // An image the browser already holds is complete as soon as src is set:
    // shown at once, 'loaded' alone.
    cached = img.complete && img.naturalWidth > 0;
    if (!cached) report('loading');

    return () => {
      img.onload = null;
      img.onerror = null;
    };
  }, [src, noSrc, placeholder, defaultImage, errorImage, onLoad, onError, transitionDuration]);

  useEffect(() => {
    if (fade !== 'start') return;
    const frame = requestAnimationFrame(() => setFade('run'));
    return () => cancelAnimationFrame(frame);
  }, [fade]);

  const fadeStyle: React.CSSProperties | undefined =
    fade === 'start' ? { opacity: 0 }
    : fade === 'run' ? { opacity: 1, transition: `opacity ${transitionDuration}ms ease-out` }
    : undefined;

  const objectFitMap: Record<string, string> = {
    cover: 'object-cover',
    contain: 'object-contain',
    fill: 'object-fill',
    none: 'object-none',
    scaleDown: 'object-scale-down',
    fit: 'object-contain',
  };

  const objectFitClass = objectFitMap[contentMode] || 'object-contain';

  if (loading && placeholder) {
    return (
      <img
        {...rootProps}
        src={placeholder}
        alt={alt}
        className={`${className} ${objectFitClass}`}
      />
    );
  }

  if (loading) {
    return (
      <div {...rootProps} className={`${className} animate-pulse bg-gray-200`} />
    );
  }

  const noImageFallback = (
    <div {...rootProps} className={`${className} bg-gray-100 flex items-center justify-center`}>
      <svg className="w-8 h-8 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
      </svg>
    </div>
  );

  if (error && !errorImage && !defaultImage) {
    return noImageFallback;
  }

  if (!imageUrl) {
    // src was empty/unset and there is no placeholder: render the same
    // no-image fallback as a failed load. Never emit <img src=""> — React
    // logs a console error and the browser may re-download the page.
    return noImageFallback;
  }

  return (
    <img
      {...rootProps}
      style={fadeStyle ? { ...style, ...fadeStyle } : style}
      src={imageUrl}
      alt={alt}
      loading={fetchHint}
      className={`${className} ${objectFitClass}`}
    />
  );
};

export default NetworkImage;
